{"content":"from mdtable import to_markdown

def test_example():
    rows = [{"name": "Ada", "score": 9.5}, {"name": "Grace Hopper", "score": 10, "note": "a|b"}]
    expected = "| name         | score | note |\n| ------------ | ----: | ---- |\n| Ada          |   9.5 |      |\n| Grace Hopper |    10 | a\\|b |"
    result = to_markdown(rows)
    print(f"Result:\n{repr(result)}")
    print(f"Expected:\n{repr(expected)}")
    assert result == expected

def test_empty_rows():
    assert to_markdown([]) == ""

def test_empty_rows_with_columns():
    assert to_markdown([], columns=["name", "score"]) == "| name | score |\n| --- | --- |"

if __name__ == "__main__":
    try:
        print("Testing example...")
        test_example()
        print("Example passed!")
    except Exception as e:
        print(f"Example failed: {e}")

    try:
        print("\nTesting empty rows...")
        test_empty_rows()
        print("Empty rows passed!")
    except Exception as e:
        print(f"Empty rows failed: {e}")

    try:
        print("\nTesting empty rows with columns...")
        test_empty_rows_with_columns()
        print("Empty rows with columns passed!")
    except Exception as e:
        print(f"Empty rows with columns failed: {e}")
